# geometry.py
"""Geometric calculations for common 3D shapes."""

from __future__ import annotations

import math
from numbers import Real

__all__ = [
    "cylinder_volume",
    "cylinder_surface_area",
    "sphere_volume",
    "sphere_surface_area",
    "cone_volume",
    "cone_surface_area",
]


def _validate_non_negative(**kwargs: float) -> None:
    """Raise ValueError if any provided value is negative or non-numeric."""
    for name, value in kwargs.items():
        if not isinstance(value, Real) or isinstance(value, bool):
            raise TypeError(f"{name} must be a real number, got {type(value).__name__}")
        if math.isnan(value) or math.isinf(value):
            raise ValueError(f"{name} must be finite")
        if value < 0:
            raise ValueError(f"{name} must be non-negative, got {value}")


def cylinder_volume(radius: float, height: float) -> float:
    """Volume of a right circular cylinder: πr²h."""
    _validate_non_negative(radius=radius, height=height)
    return math.pi * radius**2 * height


def cylinder_surface_area(radius: float, height: float) -> float:
    """Total surface area of a closed cylinder: 2πr(r + h)."""
    _validate_non_negative(radius=radius, height=height)
    return 2 * math.pi * radius * (radius + height)


def sphere_volume(radius: float) -> float:
    """Volume of a sphere: (4/3)πr³."""
    _validate_non_negative(radius=radius)
    return (4 / 3) * math.pi * radius**3


def sphere_surface_area(radius: float) -> float:
    """Surface area of a sphere: 4πr²."""
    _validate_non_negative(radius=radius)
    return 4 * math.pi * radius**2


def cone_volume(radius: float, height: float) -> float:
    """Volume of a right circular cone: (1/3)πr²h."""
    _validate_non_negative(radius=radius, height=height)
    return (1 / 3) * math.pi * radius**2 * height


def cone_surface_area(radius: float, height: float) -> float:
    """Total surface area of a closed cone: πr(r + √(r² + h²))."""
    _validate_non_negative(radius=radius, height=height)
    slant = math.hypot(radius, height)
    return math.pi * radius * (radius + slant)
```

