function validatePasswordStrength(
    string $password,
    int $minLength = 12,
    ?callable $breachChecker = null
): array {
    $errors = [];

    // Reject non-printable / non-ASCII early. Password fields should be
    // restricted to printable ASCII to avoid normalization surprises (NFC vs
    // NFD), homoglyph attacks, and \d / [a-z] regex gaps without the /u flag.
    if (!preg_match('/^[\x21-\x7E]+$/', $password)) {
        $errors[] = 'Must contain only printable ASCII characters (no spaces).';
    }

    if (strlen($password) < $minLength) {
        $errors[] = "Must be at least {$minLength} characters.";
    }
    if (!preg_match('/[A-Z]/', $password)) {
        $errors[] = 'Must contain an uppercase letter.';
    }
    if (!preg_match('/[a-z]/', $password)) {
        $errors[] = 'Must contain a lowercase letter.';
    }
    if (!preg_match('/\d/', $password)) {
        $errors[] = 'Must contain a digit.';
    }
    if (!preg_match('/[^A-Za-z0-9]/', $password)) {
        $errors[] = 'Must contain a symbol.';
    }

    if ($breachChecker !== null && $breachChecker($password)) {
        $errors[] = 'Password appears in known breach corpora.';
    }

    return ['valid' => $errors === [], 'errors' => $errors];
}
